from collections import defaultdict

def main():
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    K = int(data[1])
    Q = int(data[2])

    scores = [K] * N
    answers = list(map(int, data[3:]))

    count_correct = defaultdict(int)

    for answer in answers:
        player = answer - 1
        if scores[player] > 0:
            scores[player] -= 1
            count_correct[player] += 1

    for player in range(N):
        if count_correct[player] == len(answers):
            scores[player] = 0

    for score in scores:
        if score <= 0:
            print("No")
        else:
            print("Yes")

if __name__ == "__main__":
    main()

